const more=document.querySelector('#navigation-toggle');const panel=document.querySelector('#navigation-panel');more?.addEventListener('click',()=>{const open=more.getAttribute('aria-expanded')!=='true';more.setAttribute('aria-expanded',String(open));panel.hidden=!open});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){panel.hidden=true;more.setAttribute('aria-expanded','false');more.focus()}});if(new URLSearchParams(location.search).has('menu')){panel.hidden=false;more.setAttribute('aria-expanded','true')}
document.querySelectorAll(".new-nav [data-page]").forEach(a=>{if(location.pathname.endsWith(a.dataset.page+".html"))a.setAttribute("aria-current","page")});
